mapper.select:
SELECT COUNT(*) > 0
FROM system_users u
JOIN system_user_role ur ON ur.user_id = u.id AND ur.tenant_id = u.tenant_id AND ur.deleted = 0
JOIN system_role r ON r.id = ur.role_id AND r.tenant_id = u.tenant_id
    AND r.deleted = 0 AND r.status = #{query.enabledStatus}
JOIN system_role_menu rm ON rm.role_id = r.id AND rm.tenant_id = u.tenant_id AND rm.deleted = 0
JOIN system_menu m ON m.id = rm.menu_id AND m.deleted = 0 AND m.status = #{query.enabledStatus}
WHERE u.id = #{query.userId} AND u.tenant_id = #{query.tenantId}
    AND u.deleted = 0 AND u.status = #{query.enabledStatus}
    AND

SELECT u.id FROM system_users u
WHERE u.id = #{query.userId} AND u.tenant_id = #{query.tenantId}
    AND u.deleted = 0 AND u.status = #{query.enabledStatus}
ORDER BY u.id FOR UPDATE

SELECT r.id FROM system_role r
WHERE r.tenant_id = #{query.tenantId} AND r.deleted = 0 AND r.status = #{query.enabledStatus}
    AND EXISTS (
        SELECT 1 FROM system_user_role ur
        WHERE ur.role_id = r.id AND ur.user_id = #{query.userId}
            AND ur.tenant_id = #{query.tenantId} AND ur.deleted = 0
    )
ORDER BY r.id FOR UPDATE
